fn copyto<T: Copy>(dst: Vec<T>, src: Vec<T>, mask: Vec<bool>) -> Vec<T> {
    // Create a new vector to hold the result
    let mut result = Vec::with_capacity(dst.len());

    // Iterate over the indices of the input vectors
    for i in 0..dst.len() {
        // Check the mask and select the appropriate value
        if mask[i] {
            result.push(src[i]); // Take from src if mask is true
        } else {
            result.push(dst[i]); // Take from dst if mask is false
        }
    }

    // Return the constructed result vector
    result
}